import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CT6jiXWi.js";const u=JSON.parse('{"title":"Sources","description":"","frontmatter":{},"headers":[],"relativePath":"pipeline/guide/sources/index.md","filePath":"pipeline/guide/sources/index.md","lastUpdated":1783805127000}'),d={name:"pipeline/guide/sources/index.md"};function s(c,e,i,n,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h1><p>The <strong>source</strong> side of a pipeline owns the <code>PIPELINE.READ</code> phase. A source adapter bridges a transport-specific read (OData V4, OData V2, REST, CQN) to a uniform streaming contract the plugin consumes.</p><p>One source adapter is resolved per pipeline at registration time.</p><h2 id="resolution-order" tabindex="-1">Resolution order <a class="header-anchor" href="#resolution-order" aria-label="Permalink to &quot;Resolution order&quot;">​</a></h2><p><code>addPipeline(...)</code> resolves the source adapter in this order:</p><ol><li><code>config.source.adapter</code> — class reference extending <code>BaseSourceAdapter</code>. Full control; skips everything below.</li><li><code>config.source.kind</code> — explicit transport selector: <code>&#39;cqn&#39; | &#39;odata&#39; | &#39;odata-v2&#39; | &#39;hcql&#39; | &#39;rest&#39;</code>.</li><li><code>cds.requires.&lt;service&gt;.kind</code> (or <code>remote.kind</code>) — auto-detected for annotation-wired pipelines. Unknown values fall back to <code>RemoteCqnAdapter</code>.</li></ol><h2 id="built-in-source-adapters" tabindex="-1">Built-in source adapters <a class="header-anchor" href="#built-in-source-adapters" aria-label="Permalink to &quot;Built-in source adapters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source <code>cds.requires.&lt;service&gt;.kind</code></th><th>Adapter</th><th>Page</th></tr></thead><tbody><tr><td><code>odata</code> (OData V4)</td><td><code>RemoteCqnAdapter</code></td><td><a href="./odata.html">Remote CQN (OData &amp; HCQL)</a></td></tr><tr><td><code>odata-v2</code></td><td><code>RemoteCqnAdapter</code></td><td><a href="./odata.html">Remote CQN (OData &amp; HCQL)</a></td></tr><tr><td><code>hcql</code></td><td><code>RemoteCqnAdapter</code></td><td><a href="./odata.html">Remote CQN (OData &amp; HCQL)</a></td></tr><tr><td><code>rest</code></td><td><code>RestAdapter</code></td><td><a href="./rest.html">REST</a></td></tr><tr><td><code>cqn</code> / <code>postgres</code> / <code>hana</code> / <code>sqlite</code> / <code>better-sqlite</code> / in-process CAP services</td><td><code>CqnAdapter</code></td><td><a href="./cqn.html">CQN</a></td></tr><tr><td>Anything else</td><td>Register a <a href="./custom.html">custom source adapter</a></td><td></td></tr></tbody></table><ul><li><p><strong><a href="./odata.html">Remote CQN (OData &amp; HCQL)</a></strong> — CQN reads against remote CAP services. CAP selects OData or HCQL on the wire. Delta modes (<code>timestamp</code>, <code>key</code>, <code>datetime-fields</code>), server-driven paging, consumption-view column restriction including flattened associations when HCQL is available.</p></li><li><p><strong><a href="./rest.html">REST</a></strong> — Plain JSON over HTTP — no CDS model. Cursor / offset / page pagination, configurable delta URL parameter, nested-response extraction via <code>dataPath</code>.</p></li><li><p><strong><a href="./cqn.html">CQN</a></strong> — In-process CAP services and <code>cds.requires</code> DB bindings (<code>postgres</code>, <code>hana</code>, <code>sqlite</code>, …). Serves both entity-shape and query-shape reads.</p></li><li><p><strong><a href="./custom.html">Custom source adapter</a></strong> — Extend <code>BaseSourceAdapter</code> to read from a transport the plugin does not ship. Worked example: a CSV-file source adapter.</p></li></ul><h2 id="delta-strategies" tabindex="-1">Delta strategies <a class="header-anchor" href="#delta-strategies" aria-label="Permalink to &quot;Delta strategies&quot;">​</a></h2><p>Source adapters translate the pipeline&#39;s <code>config.delta</code> + the tracker watermark into a source-side predicate (OData <code>$filter</code>, REST query param, CQN <code>WHERE</code>, …):</p><table tabindex="0"><thead><tr><th>Strategy</th><th>Watermark</th><th>Typical use</th></tr></thead><tbody><tr><td><strong>timestamp</strong></td><td><code>tracker.lastSync</code> (ISO timestamp)</td><td>Most common. Requires a reliable <code>modifiedAt</code>-style field on the source.</td></tr><tr><td><strong>key-based</strong></td><td><code>tracker.lastKey</code> (primary-key value)</td><td>Append-only feeds where rows are keyed monotonically.</td></tr><tr><td><strong>datetime-fields</strong></td><td>Per-field timestamps in a composite watermark</td><td>Sources exposing several independently updated timestamps.</td></tr></tbody></table><p>All three are implemented for OData V4 and V2. REST supports <code>timestamp</code>. CQN supports <code>timestamp</code> and <code>key</code>. Query-shape pipelines (with <code>source.query</code>) sidestep delta entirely — see <a href="./../concepts/inference.html">Concepts → Inference rules</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../concepts/terminology.html">Concepts → Terminology</a> — source / target / tracker vocabulary.</li><li><a href="./../concepts/inference.html">Concepts → Inference rules</a> — read-shape inference and registration validation.</li><li><a href="./../targets/">Targets</a> — the peer section covering the WRITE phase.</li></ul>',15)])])}const m=t(d,[["render",s]]);export{u as __pageData,m as default};
